"""
All generated text output: TypeScript for MakeCode Arcade and the tuning report.

Pure functions of conversion results, so every front end produces the same code.
"""

from collections.abc import Sequence
from typing import TYPE_CHECKING

from midi2mkcd.arcade.music import encode_song_to_hex
from midi2mkcd.utils.format import format_ts_str_array

if TYPE_CHECKING:
    from midi2mkcd.api import ConversionResult, OutputFormat
    from midi2mkcd.tuning import InstrumentUsage

GENERATED_BY = (
    "// Generated by https://github.com/UnsignedArduino/MIDI-to-MakeCode-Arcade"
)


def song_hex(result: ConversionResult) -> str:
    """Return the encoded song as raw hex digits."""
    return encode_song_to_hex(result.song)


def _hex_literal(result: ConversionResult) -> str:
    return f"hex`{song_hex(result)}`"


def _play_statement(result: ConversionResult) -> str:
    return (
        f"music.play(music.createSong(\n"
        f"  {_hex_literal(result)}\n"
        f"), music.PlaybackMode.UntilDone);"
    )


def _comment_lines(comments: Sequence[str]) -> list[str]:
    return [f"// {comment}" for comment in comments]


def to_typescript(result: ConversionResult, format: OutputFormat = "hex") -> str:
    """
    Render a conversion result as TypeScript.

    The "Generated by" header is added for every format except a plain `"hex"`
    literal, which stays bare so it can be pasted into existing code, unless the
    result has comments to show.

    :param result: The conversion result.
    :param format: `"hex"`, `"play"` or `"visualizer"`.
    :return: The generated code.
    """
    if format == "hex":
        body = _hex_literal(result)
    elif format == "play":
        body = _play_statement(result)
    elif format == "visualizer":
        body = (
            f"const songHex = {_hex_literal(result)};\n"
            f"const midiDrumNoteMap: number[] = {result.drum_idx_to_midi_drum};\n"
            f"const trackInstrumentMap: number[] = "
            f"{result.track_idx_to_midi_instrument};\n"
            f"const lyricTicks: number[] = {result.lyric_ticks};\n"
            f"const lyricTexts: string[] = {format_ts_str_array(result.lyric_texts)};\n"
        )
    else:
        raise ValueError(f"Unknown output format: {format!r}")

    lines = _comment_lines(result.comments)
    if format != "hex" or lines:
        lines.insert(0, GENERATED_BY)
    return "\n".join([*lines, body])


def sampler(
    title: str, label: str, samples: Sequence[tuple[int, ConversionResult]]
) -> str:
    """
    Render a program that plays several conversions one after another, showing each
    one's number as the score so you can tell which is playing.

    :param title: Describes the sample, e.g. "melodic instrument sample".
    :param label: Names the numbers being sampled, e.g. "instruments".
    :param samples: (number shown as the score, conversion result) pairs, in order.
    :return: The generated code.
    """
    numbers = [number for number, _ in samples]
    out = f"{GENERATED_BY}\n// generated {title}\n// {label} {numbers}\n"
    for number, result in samples:
        for line in _comment_lines(result.comments):
            out += f"{line}\n"
        out += f"info.setScore({number});\n{_play_statement(result)}\n"
    return out


def usage_report(usages: Sequence[InstrumentUsage]) -> str:
    """
    Render `tuning.report` output as a plain-text table.

    :param usages: The instrument usages, in display order.
    :return: The table, one line per usage after a header line, with no trailing
     newline.
    """
    headers = ("kind", "number", "notes", "range", "velocity", "mapped")
    rows = [
        (
            u.kind,
            str(u.number),
            str(u.note_count),
            f"{u.lowest_note}-{u.highest_note}",
            f"{u.min_velocity}-{u.max_velocity}",
            "yes" if u.mapped else "NO",
        )
        for u in usages
    ]
    widths = [max(len(row[i]) for row in (headers, *rows)) for i in range(len(headers))]
    return "\n".join(
        "  ".join(
            cell.ljust(width) for cell, width in zip(row, widths, strict=True)
        ).rstrip()
        for row in (headers, *rows)
    )
